	var STEP_SELECTORS = {
		STEP_LI: 'liStep',
		INCOMPLETE_SPAN: 'spanInComplete',
		COMPLETE_SPAN: 'spanComplete',
		NUMBER_SPAN: 'spanStepNumber',
		WIZARD_DIV: 'wizard'
